import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 목록 size 기본 20, 최대 200
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
// 동의할 수 없는 승인 처리 상태 (마감된 기간 또는 승인된 건)
const LOCKED_STATUSES = ['마감', '승인'];

@Controller('api/v1')
export class FnSfr03204Controller {
  @Post('/attendance-requests/:attendanceRequestId/consent')
  @HttpCode(200)
  async consentAttendanceRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const idText = req.params['attendanceRequestId'];
    if (!/^[0-9]+$/.test(idText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '근태 신청 번호가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      // 본인 데이터만 동의할 수 있다
      const rows = await db.query(
        `SELECT approval_status AS "approvalStatus"
         FROM attendance_request
         WHERE attendance_request_id = CAST(:id AS bigint)
           AND employee_id = CAST(:userId AS bigint)`,
        { id: idText, userId: user.id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'ATTENDANCE_REQUEST_NOT_FOUND', '대상 근태 데이터를 찾을 수 없습니다.');
      }
      if (LOCKED_STATUSES.includes(rows[0].approvalStatus)) {
        throw new ApiError(
          409,
          'ATTENDANCE_PERIOD_CLOSED',
          '마감된 기간이거나 승인된 건은 변경할 수 없습니다. 마감 취소 후 다시 시도해 주세요.',
        );
      }
      // 가정: 동의 일시를 저장할 컬럼이 없어 수정 일시(updated_at)를 동의 시각으로 쓴다
      const updated = await db.query(
        `UPDATE attendance_request
         SET updated_at = now()
         WHERE attendance_request_id = CAST(:id AS bigint)
           AND employee_id = CAST(:userId AS bigint)
         RETURNING updated_at AS "consentedAt", approval_status AS "approvalStatus"`,
        { id: idText, userId: user.id },
      );
      return updated[0];
    });
  }

  @Get('/attendance-summaries')
  async listAttendanceSummaries(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const q = checks.queryOf(req.query);
    const month = String(q['month'] ?? '');
    if (!/^[0-9]{4}-(0[1-9]|1[0-2])$/.test(month)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 기간은 YYYY-MM 형식으로 입력해 주세요.');
    }
    const pageText = String(q['page'] ?? '0');
    const sizeText = String(q['size'] ?? String(DEFAULT_SIZE));
    if (!/^[0-9]+$/.test(pageText) || !/^[0-9]+$/.test(sizeText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기는 숫자로 입력해 주세요.');
    }
    const page = Number(pageText);
    const size = Math.min(Math.max(Number(sizeText), 1), MAX_SIZE);
    const monthStart = month + '-01';
    return transaction(async (db) => {
      // 가정: 조회 월과 기간이 겹치는 본인 근태 건을 유형·상태별로 집계한다
      const where = `FROM attendance_request
        WHERE employee_id = CAST(:userId AS bigint)
          AND start_date < (CAST(:monthStart AS date) + interval '1 month')
          AND end_date >= CAST(:monthStart AS date)
        GROUP BY attendance_type, approval_status`;
      const base = { userId: user.id, monthStart };
      const items = await db.query(
        `SELECT attendance_type AS "attendanceType",
                approval_status AS "approvalStatus",
                COUNT(*) AS "count",
                CAST(NULL AS timestamptz) AS "consentedAt"
         ${where}
         ORDER BY attendance_type, approval_status
         LIMIT :size OFFSET :offset`,
        { ...base, size, offset: page * size },
      );
      const totals = await db.query(`SELECT COUNT(*) AS "total" FROM (SELECT 1 ${where}) t`, base);
      return { items, page, size, total: Number(totals[0].total) };
    });
  }
}

