import { useState } from 'react';
import {
  call, useData, Badge, Num, DateText, Filters, Band, DataTable, Pager, Drawer, Form, Field,
  TextInput, LookupSelect, ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

function thisMonth(): string {
  const now = new Date();
  const m = String(now.getMonth() + 1).padStart(2, '0');
  return now.getFullYear() + '-' + m;
}

export default function FnSfr03204Page({ role, notify }: PageProps) {
  const [monthInput, setMonthInput] = useState<string>(thisMonth());
  const [month, setMonth] = useState<string>(thisMonth());
  const [pageNo, setPageNo] = useState<number>(0);
  const [consentOpen, setConsentOpen] = useState<boolean>(false);
  const [requestId, setRequestId] = useState<number | string>('');

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/attendance-summaries', role, undefined, { month, page: pageNo }),
    [month, pageNo],
  );

  const search = () => {
    setPageNo(0);
    setMonth(monthInput);
  };

  const reset = () => {
    setMonthInput(thisMonth());
    setPageNo(0);
    setMonth(thisMonth());
  };

  const submitConsent = async () => {
    if (requestId === '' || requestId === undefined) {
      throw new Error('동의할 근태 신청을 선택해 주세요.');
    }
    await call('POST', '/attendance-requests/' + requestId + '/consent', role);
    notify('근무시간에 동의했습니다.');
    setConsentOpen(false);
    setRequestId('');
    reload();
  };

  return (
    <div className="doc">
      <section className="box">
        <h2>근태집계 현황</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 기간(월 단위)" required hint="YYYY-MM 형식">
            <TextInput value={monthInput} onChange={setMonthInput} placeholder="2025-01" />
          </Field>
        </Filters>
        <Band total={data?.total}>
          <button onClick={() => setConsentOpen(true)}>근무시간 동의</button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        {loading ? <p>불러오는 중입니다.</p> : null}
        <DataTable
          columns={[
            { key: 'attendanceType', label: '근태 유형' },
            { key: 'approvalStatus', label: '승인 처리 상태', render: (r: Row) => <Badge value={r.approvalStatus} /> },
            { key: 'count', label: '건수', render: (r: Row) => <Num value={r.count} /> },
            { key: 'consentedAt', label: '동의 일시', render: (r: Row) => <DateText value={r.consentedAt} time /> },
          ]}
          rows={data?.items ?? []}
          empty="조회 결과가 없습니다. 조회 기간을 바꿔 다시 조회해 주세요."
        />
        <Pager page={data?.page ?? 0} size={data?.size ?? 20} total={data?.total ?? 0} onPage={setPageNo} />
      </section>
      {consentOpen ? (
        <Drawer title="근무시간 동의" onClose={() => setConsentOpen(false)}>
          <Form
            onSubmit={submitConsent}
            submit="동의"
            note="마감된 기간이거나 승인된 건은 동의할 수 없습니다."
          >
            <Field label="근태 신청" required wide>
              <LookupSelect table="attendance_request" role={role} value={requestId} onChange={setRequestId} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
